fn choose(indices: Vec<u8>, choices: Vec<Vec<f64>>) -> Vec<f64> {
    // The result will have the same length as `indices`.
    let mut result = Vec::with_capacity(indices.len());

    for (i, &idx) in indices.iter().enumerate() {
        // idx is guaranteed to be a valid row index,
        // and each row has length == indices.len(), so `row[i]` is valid.
        let row = &choices[idx as usize];
        result.push(row[i]);
    }

    result
}

